class Solution {
    List<String> res = new ArrayList<>();
    List<Character> path = new ArrayList<>();
    public List<String> letterCombinations(String digits) {
        String[] numStrings = { "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz" };
        backtracking(digits,numStrings,0);
        return res;
    }
    private String path2String() {
        StringBuilder sb = new StringBuilder();
        for (Character c : path) {
            sb.append(c);
        }
        return sb.toString();
    }
    private void backtracking(String digits, String[] numStrings, int startIndex) {
        if (digits.length() == path.size()){
            res.add(path2String());
            return;
        }
        String str = numStrings[digits.charAt(startIndex)-'0'];
        for(int i = 0;i<str.length();i++){
            path.addLast(str.charAt(i));
            backtracking(digits,numStrings,startIndex+1);
            path.removeLast();
        }
    }
}
